// Native browser IndexedDB/Web Locks contract. Transport below is controlled;
// actual authentication, uploads and atomic server attachment have separate native tests.
import {openOfflineAttachmentQueue,mountOfflineAttachmentQueue} from '/runtime/offline-attachments.js';
const results=document.querySelector('#results'),report=document.querySelector('#report'),passed=[];
const assert=(value,message)=>{if(!value)throw new Error(message);};
const reject=async(work,message)=>{let failed=false;try{await work();}catch{failed=true;}assert(failed,message);};
const record=name=>{passed.push(name);const li=document.createElement('li');li.textContent=name;results.append(li);};
const active=[];
const probe=document.createElement('button');probe.type='button';probe.id='owned-input-probe';let clicks=0;probe.textContent='Browser input probe: 0';probe.onclick=()=>{probe.textContent='Browser input probe: '+(++clicks);};document.querySelector('main').append(probe);
async function run(){
  assert(indexedDB&&navigator.locks,'Native storage and locks required.');
  let account='owned-alice',loseMutation=true,loseUpload=false,uploads=0,sends=0,concurrency=0,peak=0,hold;
  const objects=new Map(),receipts=new Map(),namespace='owned-storage-'+crypto.randomUUID(),reference={kind:'mutation',path:'notes.attach'};
  const bucket={async stat(key){if(hold)await hold;return objects.get(key)??null;},async upload(input){input.assertCurrent();concurrency++;peak=Math.max(peak,concurrency);try{await new Promise(resolve=>setTimeout(resolve,10));input.assertCurrent();assert(input.ifSha256===null,'Expected absence required.');assert(!objects.has(input.key),'No replacement permitted.');uploads++;
    const object={id:'owned_'+crypto.randomUUID(),generation:'owned_'+crypto.randomUUID(),bucket:'files',key:input.key,ownerId:'owned-alice',size:input.value.size,sha256:input.expectedSha256,contentType:input.contentType,visibility:'private'};objects.set(input.key,object);if(loseUpload){loseUpload=false;throw new TypeError('Controlled lost upload acknowledgment.');}return object;}finally{concurrency--;}}};
  const client={async mutateOnce(ref,input,receipt){sends++;assert(receipt.userId==='owned-alice','Original account required.');const prior=receipts.get(receipt.key),body=JSON.stringify(input);if(prior)assert(prior===body,'Exact replay arguments required.');else receipts.set(receipt.key,body);if(loseMutation){loseMutation=false;throw new TypeError('Controlled lost mutation acknowledgment.');}}};
  const options={namespace,userId:'owned-alice',bucketName:'files',bucket,client,currentUser:()=>account,maxItems:2,maxBlobBytes:10,maxTotalBytes:15};
  let first=await openOfflineAttachmentQueue(options),second=await openOfflineAttachmentQueue(options);active.push(first,second);
  await Promise.all([first.enqueue(reference,{id:'record-a'},new Blob(['abcdef'],{type:'text/plain; charset=utf-8'})),second.enqueue(reference,{id:'record-b'},new Blob(['12345678'],{type:'text/plain'}))]);
  assert((await first.snapshot()).length===2,'Concurrent enqueue persisted both Blobs.');
  await reject(()=>first.enqueue(reference,{id:'overflow'},new Blob(['xx'])), 'Atomic count/byte bound required.');
  const before=await first.snapshot(),id=before[0].id;assert(!('blob' in before[0])&&!('input' in before[0]),'Metadata-only snapshot required.');record('Native IndexedDB bounds concurrent writes and preserves binary queue data.');
  await first.flush();assert(receipts.size===1,'Lost acknowledgment leaves one controlled effect.');assert((await first.snapshot())[0].status==='pending','Unknown acknowledgment remains pending.');first.dispose();second.dispose();
  first=await openOfflineAttachmentQueue(options);second=await openOfflineAttachmentQueue(options);active.push(first,second);assert((await first.snapshot()).length===2,'Native reopen retained queued Blob state.');await first.retry(id);await Promise.all([first.flush(),second.flush()]);
  assert(receipts.size===2&&uploads===2&&peak===1,'Native Web Locks serialize sends without extra uploads.');assert((await first.snapshot()).length===0,'Acknowledged items removed atomically.');record('Native reopen and Web Locks preserve exact upload and mutation replay identity.');
  loseUpload=true;const lost=await first.enqueue(reference,{id:'upload-lost'},new Blob(['lost'],{type:'text/plain'}));await first.flush();const uploaded=uploads;await first.retry(lost);await first.flush();assert(uploads===uploaded&&receipts.size===3,'Lost upload reconciles existing completed key.');record('Unknown upload acknowledgment reconciles the unique object before sending.');
  const wrong=await first.enqueue(reference,{id:'wrong-object'},new Blob(['wrong'],{type:'text/plain'}));const pending=(await first.snapshot())[0];objects.set(pending.key,{id:'owned_wrong',generation:'owned_wrong',bucket:'files',key:pending.key,ownerId:'owned-alice',size:pending.size,sha256:'0'.repeat(64),contentType:'text/plain',visibility:'private'});const sendsBefore=sends;await first.flush();assert((await first.snapshot())[0].status==='failed'&&sends===sendsBefore,'Wrong object cannot attach.');
  const disposeView=mountOfflineAttachmentQueue(document.querySelector('#view'),first);await new Promise(resolve=>setTimeout(resolve,20));assert(!document.querySelector('#view').textContent.includes('wrong-object'),'Arguments excluded from view.');disposeView();await first.discard(wrong);record('Mismatched object pauses work and metadata view omits mutation arguments.');
  let release;hold=new Promise(resolve=>release=resolve);await first.enqueue(reference,{id:'account-switch'},new Blob(['a'],{type:'text/plain'}));const blocked=first.flush().then(()=>false,()=>true);await new Promise(resolve=>setTimeout(resolve,20));account='owned-bob';await reject(()=>first.snapshot(),'Switched account cannot read storage.');release();assert(await blocked,'Account loss stops the held send.');assert(sends===sendsBefore,'No attachment send after account loss.');hold=undefined;account='owned-alice';record('Current-account loss closes native storage and prevents late attachment sends.');
  const databaseName=`clank.attachments.v1:${encodeURIComponent(namespace)}:owned-alice`;const db=await new Promise((resolve,reject)=>{const r=indexedDB.open(databaseName,1);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
  await new Promise((resolve,reject)=>{const tx=db.transaction('items','readwrite'),store=tx.objectStore('items'),request=store.getAll();request.onsuccess=()=>{const row=request.result[0];row.owner='owned-bob';store.put(row);};tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);});db.close();
  await reject(()=>openOfflineAttachmentQueue(options),'Corrupt ownership is refused, not overwritten.');record('A corrupt native IndexedDB owner binding fails without sending or clearing it.');
  report.dataset.status='passed';report.textContent=`${passed.length} native browser storage checks passed. Upload/backend transports here are controlled fixtures; native server tests provide separate authentication and publication evidence.`;
}
run().catch(error=>{report.dataset.status='failed';report.textContent=String(error?.stack??error).slice(0,5000);}).finally(()=>{for(const queue of active)queue.dispose();});
